import math

sigma = 46.3
A = 37.0

def phi(z):
    return 0.5 * (1.0 + math.erf(z / math.sqrt(2)))

def pass_deposit(x, y, x_min, x_max, y_line):
    # Deposit at (x, y) from a pass along [x_min, x_max] at y_line
    # In middle of line: line profile is A * exp(-(y-y_line)^2 / (2*sigma^2))
    factor_x = phi((x_max - x) / sigma) - phi((x_min - x) / sigma)
    return factor_x * A * math.exp(-(y - y_line)**2 / (2 * sigma**2))

def simulate_panel(margin, pitch):
    # Panel is 700 x 500
    x_min = -margin
    x_max = 700 + margin
    y_min = -margin
    y_max = 500 + margin

    # How are lines placed? Usually starting at y_min to y_max with step pitch
    n_lines = int(round((y_max - y_min) / pitch)) + 1
    # Check if lines start at y_min:
    y_lines = [y_min + i * pitch for i in range(n_lines)]

    # QC points: P1(30,30), P2(670,30), P3(30,470), P4(670,470), P5(350,250)
    qc_pts = {
        "P1": (30, 30),
        "P2": (670, 30),
        "P3": (30, 470),
        "P4": (670, 470),
        "P5": (350, 250),
    }

    qc_dft = {}
    for name, (px, py) in qc_pts.items():
        val = sum(pass_deposit(px, py, x_min, x_max, yl) for yl in y_lines)
        qc_dft[name] = val

    return qc_dft

for margin in [0, 30, 50, 60, 70, 80]:
    for pitch in [45, 50]:
        res = simulate_panel(margin, pitch)
        print(f"margin={margin:2d}, pitch={pitch:2d}: P1={res[\"P1\"]:.1f}, P5={res[\"P5\"]:.1f}")
'"}

